Definition sb1_mid (sp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 : word) (P SZ PAB nres T : Z) (ws : list word) (mm md : word) (m : mem)
    : Prop :=
  exists (jf : list byte) (b : byte) (jj : list byte) (w1 w2 w3 w4 ga gm : word) (bl : list word),
    rw_cells asegs m (bv_unsigned sp - 96) [CB 8 jf; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells asegs m i_sec_chunks [C8 (Z_to_bv 64 PAB)]
    /\ rw_cells asegs m i_sec_nres [C8 (Z_to_bv 64 nres); C8 (Z_to_bv 64 nres)]
    /\ rw_cells asegs m i_sec_sorted [C1 b; CB 7 jj; C8 w1; C8 w2; C8 w3; C8 w4]
    /\ length bl = 64%nat /\ u64arr asegs m i_sec_bylog bl /\ rw_cells asegs m i_gstat_alloc [C8 ga; C8 gm]
    /\ rw_cells asegs m i_sec_mutex [C4 (Z_to_bv 64 1)]
    /\ u64arr asegs m PAB ws /\ sec_range m PAB
    /\ rw_cells asegs m P [C8 (Z_to_bv 64 P); C8 (Z_to_bv 64 (sa_msz SZ)); C8 (Z_to_bv 64 SZ)]
    /\ rw_cells asegs m (P + 24) [C8 (Z_to_bv 64 0)]
    /\ rw_cells asegs m (P + 32) [CB (Z.to_nat (sa_msz SZ - 32)) (repeat (Z_to_bv 8 0) (Z.to_nat (sa_msz SZ - 32)))]
    /\ rw_cells asegs m (shad P) [CB 512 (repeat (Z_to_bv 8 250) 512)]
    /\ rw_cells asegs m (shad (P + 4096 + SZ))
         [CB (Z.to_nat ((sa_msz SZ - 4096 - SZ) / 8)) (repeat (Z_to_bv 8 250) (Z.to_nat ((sa_msz SZ - 4096 - SZ) / 8)))]
    /\ rw_cells asegs m (T + 2872) [C8 (Z_to_bv 64 (bv_unsigned mm + 1)); C8 (Z_to_bv 64 (bv_unsigned md + sa_msz SZ))].

Definition secalloc_B1_post (ra sp gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P SZ PAB nres T lo : Z) (ws : list word) (mm md : word) (mA : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a6' t3' t4' t5' t6' : word) (k : Z) (m' : mem),
    ms' = MSsvc (mfi0_regs (Z_to_bv 64 0xa6118) (Z_to_bv 64 (bv_unsigned sp - 96)) gp (Z_to_bv 64 tpA) t0' t1' t2' a6'
                   (PAB + 8 * nres) 0x20000 (Z_to_bv 64 P) (Z_to_bv 64 (P + sa_msz SZ)) (Z_to_bv 64 (P + 4096 + SZ))
